ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns tem http://tempuri.org/
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns inv http://schemas.datacontract.org/2004/07/InventarioLTE
---
if(payload.Tramit == "RETIRAR EN LINEA")
    soapenv#Envelope @('xmlns:inv' : inv):{
        soapenv#Header:{},
        soapenv#Body:{
            tem#GestionarInventarioLTE:{
                tem#composite:{             
                    'inv:ICCID': payload.ICCID,
                    'inv:IdPedido': payload.OrderId,
                    'inv:IdServicio': payload.ServiceId,
                    'inv:MSISDN': payload.MSISDN,
                    'inv:Operacion': "RETIRAR",
                    'inv:Tramite': payload.Tramit            
                }
            }
        }
    }
else 
    soapenv#Envelope @('xmlns:inv' : inv):{
        soapenv#Header:{},
        soapenv#Body:{
            tem#GestionarInventarioLTE:{
                tem#composite:{             
                    'inv:ICCID': payload.ICCID,
                    'inv:IdPedido': payload.OrderId,
                    'inv:IdServicio': payload.ServiceId,
                    'inv:MSISDN': payload.MSISDN,
                    "inv:NuevoIdent": payload.NewMSISDN,
                    'inv:Operacion': "COMPLETAR",
                    'inv:Tramite': payload.Tramit               
                }
            }
        }
    }
